/// Retrieves a directory listing from a unix-style path rooted at `root`. `root` may be one of:
/// - `me` for the current user's drive
/// - `union` for the union of the current user's drive and all shared drives
/// - the UUID of any drive directory
/// 
/// Paths may include wildcards like `*`.
///                 
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `root` - The root directory to list files for, or one of "me" or "union".
/// * `tail` - The unix-style path specifier to use for the file listing.
///
/// Returns
/// * The directory listing
pub async fn ls(
    ctx: &dyn RequestContext,
    root: &str,
    tail: &str,
) -> Result<DirectoryList, Error> {
    let path = "/v1/api/ulv2/drive/:root/*tail"
        .replace(":root", root)
        .replace("*tail", tail);
    let res = ctx.get(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Creates a new file or directory at a specified path rooted at `root`.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `root` - The directory into which the new entry will be created
/// * `tail` - The name of the new entry
/// * `ty` - The type of entry to create: `file` or `directory`.
/// * `mime` - The mime type of the entry to create, if this is a new file entry.
/// * `chunks` - Number of chunks to expect, if this is a new file entry.
///
/// Returns
/// * A summary of the object created
pub async fn create_entry(
    ctx: &dyn RequestContext,
    root: &str,
    tail: &str,
    ty: &str,
    mime: &str,
    chunks: i64,
) -> Result<ObjectSummary, Error> {
    let path = "/v1/api/ulv2/drive/:root/*tail"
        .replace(":root", root)
        .replace("*tail", tail);
    let mut params = ParamMap::new();
    params.insert("ty".to_owned(), ty.to_owned());
    params.insert("mime".to_owned(), mime.to_owned());
    params.insert("chunks".to_owned(), chunks.to_string());

    let body = Bytes::new();
    let res = ctx.post(&path, body, "text/plain", Some(params), None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Retrieves a list of the top-level drive root directories that the current user has access to.
///
/// # Arguments
///
/// * `ctx` - A request context object
///
/// Returns
/// * A listing of all the directory roots.
pub async fn get_roots(
    ctx: &dyn RequestContext,
) -> Result<DirectoryList, Error> {
    let path = "/v1/api/ulv2/drive";
    let res = ctx.get(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Creates a new file in the specified directory with the specified content. Please use the `put_file_chunk` endpoint to upload files larger than 1GB.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `root` - The directory into which the file will be uploaded
/// * `force` - Whether to overwrite the file if it already exists.
/// * `files` - The files to upload as part of a multipart upload
///
/// Returns
/// * An updated list of directory entries
pub async fn post_file(
    ctx: &dyn RequestContext,
    root: &str,
    force: bool,
    files: Vec<File>,
) -> Result<DirectoryList, Error> {
    let path = "/v1/api/ulv2/drive/:root"
        .replace(":root", root);
    let mut params = ParamMap::new();
    params.insert("force".to_owned(), if force { "true" } else  { "false" }.to_owned());

    let res = ctx.upload(&path, files).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Removes the specified drive entry from its parent directory.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `entry` - The ID of the entry to remove
///
/// Returns
/// * An updated list of directory entries
pub async fn unlink(
    ctx: &dyn RequestContext,
    entry: &str,
) -> Result<DirectoryList, Error> {
    let path = "/v1/api/ulv2/drive/:entry"
        .replace(":entry", entry);
    let res = ctx.delete(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Moves a file or directory to a new location.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `move_request` - Details of the move operation.
pub async fn move_(
    ctx: &dyn RequestContext,
    move_request: MoveRequest,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/drive/move";
    let body = Bytes::from(Vec::<u8>::from(move_request));
    ctx.post(&path, body, "application/octet-stream", None, None).await?;
    Ok(())
}

/// Copies a file or directory to a new location within the drive.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `copy_request` - Details of the copy operation.
pub async fn copy(
    ctx: &dyn RequestContext,
    copy_request: MoveRequest,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/drive/copy";
    let body = Bytes::from(Vec::<u8>::from(copy_request));
    ctx.post(&path, body, "application/octet-stream", None, None).await?;
    Ok(())
}

/// Retrieves a file by id.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the file to retrieve
///
/// Returns
/// * The contents of the file referenced by the specified ID
pub async fn get_file(
    ctx: &dyn RequestContext,
    id: &str,
) -> Result<Vec<u8>, Error> {
    let path = "/v1/api/ulv2/drive/file/:id"
        .replace(":id", id);
    let res = ctx.get(&path, None, None).await?;
    Ok(res)
}

/// Uploads a chunk of a file by file id and chunk index.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `file_id` - The ID of the file to which to set a file chunk
/// * `idx` - The index of the file chunk to set
/// * `hash` - The hash of the chunk to upload.
/// * `chunk` - Binary file chunk data
pub async fn put_file_chunk(
    ctx: &dyn RequestContext,
    file_id: &str,
    idx: i64,
    hash: &str,
    chunk: Vec<u8>,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/drive/file/:file_id/:idx"
        .replace(":file_id", file_id)
        .replace(":idx", &idx.to_string());
    let mut params = ParamMap::new();
    params.insert("hash".to_owned(), hash.to_owned());

    let body = Bytes::from(chunk);
    ctx.put(&path, body, "application/octet-stream", Some(params), None).await?;
    Ok(())
}

/// Retrieves the id of the drive root directory for the specified principal (user or group).
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `b2cid` - The principal (user or group) ID to retrieve the drive root directory for.
///
/// Returns
/// * Drive directory root ID
pub async fn get_root_id(
    ctx: &dyn RequestContext,
    b2cid: &str,
) -> Result<ObjectId, Error> {
    let path = "/v1/api/ulv2/drive/root/:b2cid"
        .replace(":b2cid", b2cid);
    let res = ctx.get(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}


